'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const path = require('node:path');
const money = require('../src/main/money.cjs');

test('every invoice total matches the dashboard pricing code to the piastre', () => {
  // Generated by test/quote-vectors.php from App\Services\Dashboard\DesktopPosQuote and the server cart rules.
  const vectors = require(path.join(__dirname, 'fixtures', 'quote-vectors.json'));
  assert.ok(vectors.length >= 400);
  for (const [index, vector] of vectors.entries()) {
    const result = money.quote(vector.catalog, vector.cart);
    for (const key of ['subtotal_cents', 'discount_cents', 'service_cents', 'delivery_cents', 'tax_cents', 'total_cents']) {
      assert.equal(result[key], vector.expected[key], `vector ${index} ${key}`);
    }
  }
});

test('money text, rounding and quantities follow the dashboard rules', () => {
  assert.equal(money.minor('12.5'), 1250);
  assert.equal(money.minor('0.05'), 5);
  assert.throws(() => money.minor('1.234'));
  assert.equal(money.decimal(27100), '271.00');
  assert.equal(money.decimal(5), '0.05');
  assert.equal(money.commission(10000, 1400), 1400);
  assert.equal(money.commission(333, 1250), 42);
  assert.equal(money.millis('1.5'), 1500);
  assert.equal(money.millis('2'), 2000);
  assert.throws(() => money.millis('1.2345'));
  assert.equal(money.lineTotal(12000, 1500), 18000);
  assert.equal(money.lineTotal(333, 333), 111);
});

test('identical lines merge before rounding, like the server cart', () => {
  const catalog = { tax_bps: 0, service_bps: 0, products: [{ id: 1, name: 'بلطي', variants: [{ option_id: '', label: 'الأساسي', unit_price_cents: 1234, quantity_mode: 'weight' }] }] };
  const split = money.quote(catalog, { items: [{ product_id: 1, quantity_mode: 'weight', quantity: '0.333' }, { product_id: 1, quantity_mode: 'weight', quantity: '0.333' }] });
  assert.equal(split.items.length, 1);
  assert.equal(split.subtotal_cents, money.lineTotal(1234, 666));
});

test('invalid carts are refused with an Arabic message', () => {
  const catalog = { tax_bps: 0, service_bps: 0, products: [{ id: 1, name: 'بلطي', variants: [{ option_id: '', label: 'الأساسي', unit_price_cents: 1000, quantity_mode: 'piece' }] }] };
  assert.throws(() => money.quote(catalog, { items: [] }), /فارغة/);
  assert.throws(() => money.quote(catalog, { items: [{ product_id: 2, quantity_mode: 'piece', quantity: '1' }] }), /غير موجود/);
  assert.throws(() => money.quote(catalog, { items: [{ product_id: 1, quantity_mode: 'piece', quantity: '1.5' }] }), /صحيحًا/);
  assert.throws(() => money.quote(catalog, { items: [{ product_id: 1, quantity_mode: 'piece', quantity: '1' }], discount_cents: 2000 }), /الخصم/);
});
